package site.hsu.hub.recruitment.adapter.out.persistence;import jakarta.persistence.*;
@Entity@Table(name="form_questions")public class FormQuestionEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="step_id",nullable=false)private Long stepId;@Column(nullable=false,length=30)private String type;@Column(nullable=false,length=300)private String label;@Column(name="is_required",nullable=false)private boolean required;@Column(name="help_text",length=500)private String helpText;@Column(length=300)private String placeholder;@Column(name="max_length")private Integer maxLength;@Column(name="display_order",nullable=false)private int order;protected FormQuestionEntity(){}public FormQuestionEntity(Long step,String type,String label,boolean required,String help,String placeholder,Integer max,int order){stepId=step;this.type=type;this.label=label;this.required=required;helpText=help;this.placeholder=placeholder;maxLength=max;this.order=order;}public Long id(){return id;}public Long stepId(){return stepId;}public String type(){return type;}public String label(){return label;}public boolean required(){return required;}public String helpText(){return helpText;}public String placeholder(){return placeholder;}public Integer maxLength(){return maxLength;}public int order(){return order;}}
